#include <algorithm>
#include <cassert>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <iostream>
using namespace std;

typedef long long int64;

const int INF = 0x3f3f3f3f;
const int MAXN = 1e7 + 10;

bool isnt_prime[MAXN];
int prime[MAXN], phi[MAXN];
int64 mfac_cnt[MAXN], mfac_sum[MAXN];

#define sum(l, r) (((r) < (l)) ? 0LL : (mfac_sum[(r)] - mfac_sum[(l) - 1]))

int main() {
    int n;
    cin >> n;

    isnt_prime[1] = true;
    phi[1] = 1;

    int prime_cnt = 0;
    for (int i = 2; i <= n; i++) {
        if (!isnt_prime[i]) {
            prime[prime_cnt++] = i;
            mfac_cnt[i]++;
            phi[i] = i - 1;
        }
        for (int j = 0; j < prime_cnt; j++) {
            if (1LL * i * prime[j] > n) break;
            int value = i * prime[j];
            isnt_prime[value] = true;
            mfac_cnt[prime[j]]++;
            if (i % prime[j] == 0) {
                phi[value] = phi[i] * prime[j];
                break;
            } else {
                phi[value] = phi[i] * (prime[j] - 1);
            }
        }
    }

    for (int i = 1; i <= n; i++) {
        mfac_sum[i] = mfac_sum[i - 1] + mfac_cnt[i];
    }

    int64 path2 = 0;
    for (int i = 1; i <= n; i++) {
        path2 += phi[i] - 1;
    }

    int64 path1 = 1LL * (n - 1) * (n - 2) / 2 - path2;
    int64 ans = path2 * 2 + path1;

    for (int i = 0; i < prime_cnt; i++) {
        ans += mfac_cnt[prime[i]] *
               sum(max(prime[i] + 1, n / prime[i] + 1),
                   max(prime[i], n / 2));
        ans -= 2LL * mfac_cnt[prime[i]] *
               sum(max(prime[i], n / 2) + 1, n);
    }

    cout << ans << endl;
    return 0;
}

#include <algorithm>
#include <iostream>
using namespace std;

using int64 = long long;

const int MAXN = 10000010;

bool isnt_prime[MAXN];
int prime[MAXN], phi[MAXN];
int64 mfac_cnt[MAXN], mfac_sum[MAXN];

#define sum(l, r) (((r) < (l)) ? 0LL : (mfac_sum[(r)] - mfac_sum[(l) - 1]))

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    isnt_prime[1] = true;
    phi[1] = 1;

    int prime_cnt = 0;
    for (int i = 2; i <= n; ++i) {
        if (!isnt_prime[i]) {
            prime[prime_cnt++] = i;
            ++mfac_cnt[i];
            phi[i] = i - 1;
        }

        for (int j = 0; j < prime_cnt; ++j) {
            int64 product = 1LL * i * prime[j];
            if (product > n) break;

            int value = static_cast<int>(product);
            isnt_prime[value] = true;
            ++mfac_cnt[prime[j]];

            if (i % prime[j] == 0) {
                phi[value] = phi[i] * prime[j];
                break;
            }

            phi[value] = phi[i] * (prime[j] - 1);
        }
    }

    for (int i = 1; i <= n; ++i) {
        mfac_sum[i] = mfac_sum[i - 1] + mfac_cnt[i];
    }

    int64 path2 = 0;
    for (int i = 1; i <= n; ++i) {
        path2 += static_cast<int64>(phi[i]) - 1;
    }

    int64 path1 = 1LL * (n - 1) * (n - 2) / 2 - path2;
    int64 ans = path2 * 2 + path1;

    for (int i = 0; i < prime_cnt; ++i) {
        ans += mfac_cnt[prime[i]] *
               sum(max(prime[i] + 1, n / prime[i] + 1),
                   max(prime[i], n / 2));

        ans -= 2LL * mfac_cnt[prime[i]] *
               sum(max(prime[i], n / 2) + 1, n);
    }

    cout << ans << '\n';
    return 0;
}

